sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var eventId = g_form.getValue('event_id');

    if (!eventId) {
        alert("Please select an Event ID.");
        return;
    }

    var ga = new GlideAjax('fetchdetailsfromeventrecordtable');
    ga.addParam('sysparm_name', 'fetchEventDetails');
    ga.addParam('sysparm_event_id', eventId);

    ga.getXMLAnswer(function(response) {
        if (!response) {
            alert("No response received from server.");
            return;
        }

        var result;
        try {
            result = JSON.parse(response);  
        } catch (e) {
            alert("Failed to parse response: " + response);
            return;
        }

        if (result.error) {
            alert(result.error);
        } else {
            // Set form fields
            if (result.taskName) {
                g_form.setValue('u_task_name', result.taskName);
            }

            if (result.dueDate) {
                g_form.setValue('due_date', result.dueDate);
            }

            if (result.isVIP !== undefined) {
                g_form.setValue('u_is_vip', result.isVIP.toString()); // convert boolean to string if needed
            }
        }
    });
}
